window.kkStations=function(host){
const root=host.attachShadow({mode:'open'});root.innerHTML="<link rel=\"stylesheet\" href=\"/kilometerkampioen/stations.css\"><button id=\"help\">Uitleg en instellingen bewaren</button><div id=\"view\"></div><p id=\"toast\" role=\"status\" aria-live=\"polite\"></p><dialog id=\"editor\"><form id=\"station-form\"><div class=\"dialog-top\"><h2 id=\"edit-title\">Station toevoegen</h2><button type=\"button\" id=\"close-editor\" aria-label=\"Sluiten\">×</button></div><label>Zoek een station<input id=\"search\" type=\"search\" placeholder=\"Bijvoorbeeld Utrecht of Zürich\" autocomplete=\"off\"></label><p id=\"station-search-status\" class=\"muted\" role=\"status\"></p><div id=\"suggestions\" aria-label=\"Stationsuggesties\" hidden></div><p id=\"station-selected\" class=\"muted\"></p><select id=\"station\" hidden aria-label=\"Gekozen station\"><option value=\"\"></option></select><p class=\"muted\">Alle Nederlandse stations uit de dienstregeling en onze aangesloten buitenlandse stations.</p><label>Stijl<select id=\"style\"><option value=\"trr\">Treinreiziger</option><option value=\"db\">DB-bord</option><option value=\"it\">Trenitalia</option><option value=\"uk\">UK</option><option value=\"sncf\">SNCF</option><option value=\"rustig\">Rustig</option><option value=\"compact\">Compact</option></select></label><fieldset><legend>Jouw vertrekfilters</legend><p class=\"muted\">Een vertrek wordt getoond als het aan minstens één filter voldoet. Zonder filters zie je alle vertrekken.</p><div id=\"filters\"></div><button type=\"button\" id=\"add-filter\">+ Filter toevoegen</button></fieldset><button class=\"primary\" type=\"submit\">Bewaar station</button><button type=\"button\" id=\"remove-station\" class=\"danger\" hidden>Verwijder uit mijn stations</button></form></dialog>\r\n<dialog id=\"help-dialog\"><h2>Mijn stations: instellingen</h2><p>Je stations, stijlen en filters worden op dit apparaat bewaard. Wissen van browsergegevens verwijdert ook je voorkeuren. Je kunt ze hieronder exporteren.</p><p>We tellen hoeveel keer een station wordt toegevoegd. We bewaren daarbij geen naam, account of apparaatnummer. Opnieuw toevoegen telt opnieuw.</p><p>Een groen vinkje betekent dat er actuele informatie zonder vertraging is ontvangen. Een klokje betekent: alleen een planning. Die kan nog wijzigen.</p><button id=\"export\">Exporteer mijn instellingen</button><label class=\"import\">Importeer instellingen<input id=\"import\" type=\"file\" accept=\"application/json\"></label><button id=\"close-help\" class=\"primary\">Begrepen</button></dialog>\r\n";
const active=()=>host.isConnected&&(window.location.hash==='#mijn-stations'||window.location.hash.startsWith('#mijn-stations/'));
const location={get hash(){return window.location.hash==='#mijn-stations'?'#tijden':window.location.hash.replace('#mijn-stations/','#station/');},set hash(value){window.location.hash=value.replace(/^#/,'').replace(/^tijden$/,'mijn-stations').replace('station/','mijn-stations/');}};
const $=s=>root.querySelector(s),view=$('#view'),editor=$('#editor'),key='treinreiziger-stations-v1';
const styles=['trr','db','it','uk','sncf','rustig','compact'];
let favorites=[],catalog=[],cache=new Map(),editing=null,timer,renderId=0,installPrompt;
function defaultStation(){return {id:'voorbeeld-utrecht',station:'nl-ut',name:'Utrecht Centraal',country:'NL',style:'trr',filters:[
 {label:'Eerste trein richting Amsterdam C',direction:'Amsterdam C'},
 {label:'Eerste trein richting Rotterdam (via Gouda)',direction:'Rotterdam Centraal',via:'Gouda'},
 {label:'Eerste trein richting Eindhoven',direction:'Eindhoven'},
 {label:'Eerste trein richting Amersfoort',direction:'Amersfoort'},
 {label:'Eerste trein richting Schiphol',direction:'Amsterdam Zuid'},
 {label:'Eerste intercity richting Arnhem',direction:'Arnhem',types:'IC'},
 {label:'Eerste ICE richting Duitsland',direction:'Köln; Dusseldorf; Frankfurt',types:'ICE'}
]};}
try{const stored=localStorage.getItem(key);favorites=stored===null?[defaultStation()]:JSON.parse(stored);if(!Array.isArray(favorites))favorites=[];if(stored===null)localStorage.setItem(key,JSON.stringify(favorites));}catch{favorites=[defaultStation()];}

const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const norm=s=>String(s||'').normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
function toast(s){$('#toast').textContent=s;$('#toast').classList.add('show');clearTimeout(timer);timer=setTimeout(()=>$('#toast').classList.remove('show'),4500);}
function save(){try{localStorage.setItem(key,JSON.stringify(favorites));}catch{toast('Opslaan is geblokkeerd. Je instellingen blijven alleen deze sessie beschikbaar.');}}
async function api(path,options){const r=await fetch('/app/api/'+path,{...options,signal:AbortSignal.timeout(75000)});const j=await r.json();if(!r.ok)throw Error(j.error||'Ophalen mislukt');return j;}
function header(k,title,description){return `<div class="eyebrow">${esc(k)}</div><h1>${esc(title)}</h1><p class="intro">${esc(description)}</p>`;}
function status(r){return r.cancelled?'<span class="status cancel" title="Geannuleerd">Uitval</span>':!r.hasRealtime?'<span class="status" title="Alleen dienstregeling, geen actuele meting" aria-label="Alleen dienstregeling">◷</span>':r.delay>0?`<span class="status ${r.delay>=5?'late':''}" aria-label="${esc(r.delay)} minuten vertraging">+${esc(r.delay)}</span>`:'<span class="status ok" aria-label="Actueel: op tijd" title="Actueel: op tijd">✓</span>';}
function matches(r,filters){return !filters?.length||filters.some(f=>{const route=[...(r.route||[]).map(s=>typeof s==='string'?s:s.name||s.station||''),r.to].map(norm);const has=t=>String(t).split(';').map(x=>norm(x.trim())).filter(Boolean).some(t=>route.some(s=>s.includes(t)));const types=(f.types||'').split(/[,;]/).map(x=>x.trim().toUpperCase()).filter(Boolean);return (!f.direction||has(f.direction))&&(!f.via||has(f.via))&&(!f.exclude||!has(f.exclude))&&(!types.length||types.some(t=>String(r.category||'').toUpperCase()===t));});}
function rowsFor(f,p){return(p.departures||[]).filter(r=>matches(r,f.filters));}
async function board(f){const c=cache.get(f.station);if(c&&Date.now()-c.at<30000)return c.data;const data=await api('board/'+encodeURIComponent(f.station));cache.set(f.station,{at:Date.now(),data});return data;}
function nextRows(rows){return rows.slice(0,2).map(r=>`<div class="mini-departure"><strong class="time">${esc(r.time)}</strong><div class="mini-destination">${esc(r.to)}<small>${esc(r.category)} ${esc(r.number)}</small></div><span class="mini-track"><small>spoor</small>${esc(r.track||'—')}</span>${status(r)}</div>`).join('');}
async function render(){if(!active())return;const token=++renderId,hash=location.hash.slice(1)||'tijden';
 if(hash==='tijden'){
  view.innerHTML='<div class="station-toolbar"><p>Jouw stations, jouw vertrekfilters</p><button id="add-station" class="primary">+ Station</button></div>'+(favorites.length?'<div class="station-grid">'+favorites.map(f=>'<article class="card station-card '+esc(f.style)+'"><button class="edit" data-edit="'+esc(f.id)+'" aria-label="Bewerk '+esc(f.name)+'">Bewerk</button><a class="station-link" href="#mijn-stations/'+encodeURIComponent(f.id)+'"><h2>'+esc(f.name)+'</h2><p class="filter-description">'+esc((f.filters||[]).length>2?f.filters.length+' vertrekfilters':(f.filters||[]).map(x=>x.label||x.direction||x.types||'Filter').join(' · ')||'Alle vertrekken')+'</p><div data-next="'+esc(f.id)+'"><p class="muted">Vertrekken laden…</p></div><span class="check-board">Check vertrekbord '+esc(f.name)+' →</span></a><a class="button all-departures" href="#mijn-stations/'+encodeURIComponent(f.id)+'?all=1">Alle vertrektijden →</a></article>').join('')+'</div>':'<div class="empty"><h2>Waar begint jouw reis?</h2><p>Voeg een station toe en bekijk je eerstvolgende vertrekken.</p><button id="empty-add" class="primary">Kies je eerste station</button></div>');
  await Promise.all(favorites.map(async f=>{try{const p=await board(f);if(token!==renderId)return;const el=[...root.querySelectorAll('[data-next]')].find(x=>x.dataset.next===f.id);if(el)el.innerHTML=nextRows(rowsFor(f,p))||'<p class="muted">Geen passend vertrek beschikbaar.</p>';}catch(e){if(token!==renderId)return;const el=[...root.querySelectorAll('[data-next]')].find(x=>x.dataset.next===f.id);if(el)el.textContent=e.message;}}));return;
 }
 if(hash.startsWith('station/')){const f=favorites.find(f=>f.id===decodeURIComponent(hash.slice(8).split('?')[0]));if(!f){location.hash='tijden';return;}view.innerHTML=`<a class="button" href="#mijn-stations">← Mijn stations</a><div class="heading"><div>${header(f.country,f.name,hash.includes('?all=1')?'Alle vertrektijden':'Jouw gefilterde vertrekbord')}</div><button data-edit="${esc(f.id)}">Instellingen</button></div><div id="departures"><p role="status">Vertrekken laden…</p></div>`;try{const p=await board(f);if(token!==renderId)return;const all=new URLSearchParams(hash.split('?')[1]||'').get('all')==='1',rows=all||!f.filters?.length?(p.departures||[]):f.filters.map(filter=>({...((p.departures||[]).find(r=>matches(r,[filter]))||{missing:true}),filterLabel:filter.label||filter.direction||filter.types||'Filter'}));$('#departures').innerHTML=`<div class="${esc(f.style)}"><div class="board"><div class="departure table-head"><span>Tijd</span><span>Bestemming</span><span>Spoor</span><span>Status</span></div>${rows.length?rows.slice(0,60).map(r=>`${r.filterLabel?`<div class="filter-result-label">${esc(r.filterLabel)}</div>`:''}${r.missing?'<p class="muted filter-empty">Geen passend vertrek gevonden.</p>':`<div class="departure"><span class="time">${esc(r.time)}</span><span class="dest">${esc(r.to)}<small>${esc(r.category)} ${esc(r.number)}</small></span><span>${esc(r.track||'—')}</span>${status(r)}</div>`}`).join(''):'<p class="empty">Geen vertrekken die aan je filters voldoen. Pas je filters aan of probeer het later opnieuw.</p>'}</div></div><p class="source">Bron: ${esc(p.source)}<br>${esc(p.notice)}<br>◷ Alleen planning · ✓ Actueel op tijd · +5 Vijf minuten vertraging<br>Opgehaald om ${new Date().toLocaleTimeString('nl-NL',{hour:'2-digit',minute:'2-digit'})}</p><button id="refresh">Ververs</button> <a class="button" href="#mijn-stations/${encodeURIComponent(f.id)}${all?'':'?all=1'}">${all?'Mijn vertrekfilters':'Alle vertrektijden'}</a>`;}catch(e){if(token===renderId)$('#departures').innerHTML=`<p>${esc(e.message)}</p><button id="refresh">Opnieuw proberen</button>`;}return;}

}
function stationOptions(search='',selected=''){
 const query=norm(search.trim());
 const list=catalog.filter(s=>norm(s.name).includes(query)).sort((a,b)=>Number(norm(b.name).startsWith(query))-Number(norm(a.name).startsWith(query))||a.name.localeCompare(b.name,'nl')).slice(0,10);
 const chosen=catalog.find(s=>s.id===selected);
 $('#station').innerHTML='<option value=""></option>'+(chosen?`<option value="${esc(chosen.id)}">${esc(chosen.name)}</option>`:'');$('#station').value=selected||'';
 $('#station-selected').textContent=chosen?'Gekozen: '+chosen.name:'';
 $('#suggestions').innerHTML=chosen?'':list.map(s=>`<button type="button" data-station-choice="${esc(s.id)}">${esc(s.name)}<small>${esc(s.country)}</small></button>`).join('');
 $('#station-search-status').textContent=chosen?'':!catalog.length?'Stations laden…':!list.length?'Geen stations gevonden. Probeer een andere naam.':query?'Kies een station uit de suggesties.':'Begin met typen om een station te zoeken.';
 $('#suggestions').hidden=!!chosen||!query;
}
root.addEventListener('click',e=>{const b=e.target.closest('[data-station-choice]');if(!b)return;const s=catalog.find(s=>s.id===b.dataset.stationChoice);if(s){$('#search').value=s.name;stationOptions(s.name,s.id);$('#style').focus();}});
$('#search').addEventListener('keydown',e=>{if(e.key==='ArrowDown'&&!$('#suggestions').hidden){e.preventDefault();$('#suggestions button')?.focus();}if(e.key==='Enter'){e.preventDefault();if(!$('#suggestions').hidden)$('#suggestions button')?.click();}});
$('#suggestions').addEventListener('keydown',e=>{const buttons=[...$('#suggestions').querySelectorAll('button')],index=buttons.indexOf(root.activeElement);if(e.key==='ArrowDown'||e.key==='ArrowUp'){e.preventDefault();buttons[(index+(e.key==='ArrowDown'?1:buttons.length-1))%buttons.length]?.focus();}if(e.key==='Escape'){$('#suggestions').hidden=true;$('#search').focus();}});

function addFilter(f={}){const el=document.createElement('div');el.className='filter';el.innerHTML=`<label>Naam van filter<input data-field="label" maxlength="60" value="${esc(f.label)}" placeholder="Bijvoorbeeld richting Utrecht"></label><label>Richting / tussenstation<input data-field="direction" maxlength="80" value="${esc(f.direction)}" placeholder="Bijvoorbeeld Utrecht"></label><label>Treinsoorten<input data-field="types" maxlength="80" value="${esc(f.types)}" placeholder="Bijvoorbeeld IC, ICE"></label><label>Moet via<input data-field="via" maxlength="80" value="${esc(f.via)}" placeholder="Optioneel"></label><label>Niet via<input data-field="exclude" maxlength="80" value="${esc(f.exclude)}" placeholder="Optioneel"></label><button type="button" class="remove-filter">Verwijder filter</button>`;$('#filters').append(el);}
async function openEditor(id){editing=id||null;const f=favorites.find(f=>f.id===id);$('#edit-title').textContent=f?'Station instellen':'Station toevoegen';$('#style').value=f?.style||'trr';$('#search').disabled=!!f;$('#search').value=f?.name||'';$('#station-search-status').textContent='Stations laden…';$('#station-selected').textContent='';$('#suggestions').innerHTML='';$('#filters').innerHTML='';for(const x of f?.filters||[])addFilter(x);$('#remove-station').hidden=!f;editor.showModal();try{if(!catalog.length)catalog=(await api('stations')).stations;stationOptions($('#search').value,f?.station);$('#station').disabled=!!f;$('#search').disabled=!!f;}catch(e){toast(e.message);}}
root.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.edit)void openEditor(b.dataset.edit);if(['add-station','empty-add'].includes(b.id))void openEditor();if(b.id==='close-editor')editor.close();if(b.id==='add-filter'){if($('#filters').children.length>=8){toast('Je kunt maximaal 8 filters toevoegen.');return;}addFilter();}if(b.classList.contains('remove-filter'))b.closest('.filter').remove();if(b.id==='remove-station'){favorites=favorites.filter(f=>f.id!==editing);save();editor.close();location.hash='tijden';void render();}if(['retry','refresh'].includes(b.id)){cache.clear();void render();}if(b.id==='help')$('#help-dialog').showModal();if(b.id==='close-help')$('#help-dialog').close();});
$('#search').addEventListener('input',e=>stationOptions(e.target.value));
$('#station-form').addEventListener('submit',async e=>{e.preventDefault();const station=catalog.find(s=>s.id===$('#station').value);if(!station){$('#station-search-status').textContent='Kies eerst een station uit de suggesties.';$('#search').focus();return;}const filters=[...$('#filters').children].map(el=>Object.fromEntries([...el.querySelectorAll('[data-field]')].map(i=>[i.dataset.field,i.value.trim()]))).filter(f=>f.direction||f.types||f.via||f.exclude);if(!editing&&favorites.length>=20){toast('Je kunt maximaal 20 stationstegels toevoegen.');return;}const f={id:editing||crypto.randomUUID(),station:station.id,name:station.name,country:station.country,style:$('#style').value,filters};if(editing)favorites=favorites.map(x=>x.id===editing?f:x);else favorites.push(f);const isNew=!editing;save();editor.close();location.hash='tijden';void render();if(isNew)void api('added',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({station:station.id})}).catch(()=>{});});
$('#export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(favorites,null,2)],{type:'application/json'}));a.download='treinreiziger-stations.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);};
$('#import').onchange=async e=>{try{const file=e.target.files[0];if(!file||file.size>100000)throw Error();const a=JSON.parse(await file.text());if(!Array.isArray(a)||a.length>20||a.some(f=>typeof f.station!=='string'||typeof f.name!=='string'||!styles.includes(f.style)||!Array.isArray(f.filters)||f.filters.length>8))throw Error();favorites=a.map(f=>({...f,id:crypto.randomUUID(),filters:f.filters.map(x=>Object.fromEntries(['label','direction','types','via','exclude'].map(k=>[k,String(x[k]||'').slice(0,80)])))}));save();$('#help-dialog').close();location.hash='tijden';void render();}catch{toast('Dit instellingenbestand kon niet worden gelezen.');}};

const controller=new AbortController(),opts={signal:controller.signal};
window.addEventListener('hashchange',()=>{renderId++;if(active())void render();else{editor.close();$('#help-dialog').close();}},opts);
window.addEventListener('online',()=>{if(active()){cache.clear();void render();}},opts);
document.addEventListener('visibilitychange',()=>{if(active()&&!document.hidden){cache.clear();void render();}},opts);
const refreshTimer=setInterval(()=>{if(!host.isConnected){clearInterval(refreshTimer);clearTimeout(timer);controller.abort();return;}if(active()&&!document.hidden){cache.clear();void render();}},60000);
void render();
};
